$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$out="$root\M78WindowsTailResults";$base='http://192.168.122.1:8872';$name='m78-windows-tail-owned-inventory-v2'
try{if(Test-Path "$out\$name.json"){throw 'Preserve prior inventory'};$files=@();foreach($path in @("$root\M78ContinuationBuild","$root\M78ContinuationResults")){foreach($f in Get-ChildItem -LiteralPath $path -Recurse -File){$files+=@{path=$f.FullName;bytes=$f.Length}}};foreach($f in Get-ChildItem -LiteralPath "$root\Build\Release" -Filter 'm78_*.exe' -File){$files+=@{path=$f.FullName;bytes=$f.Length}};$large=@($files|Sort-Object -Property @{Expression={$_.bytes}} -Descending|Select-Object -First 35);$totals=@();foreach($namePart in @('combined-v1','combined-v2','diagnostic-warm-v1')){$a=@($files|Where-Object {$_.path -like "*\$namePart\*"});$sum=0;foreach($item in $a){$sum+=[long]$item.bytes};$totals+=@{name=$namePart;fileCount=$a.Count;bytes=$sum}};@{freeBytes=(Get-PSDrive C).Free;largestOwnedFiles=$large;namedScratchTotals=$totals;scope='Only read-only inventory; no deletion. Actual current library/package/results/source remain protected.'}|ConvertTo-Json -Depth 6|Set-Content "$out\$name.json" -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/$name.json" -Method Post -InFile "$out\$name.json"|Out-Null}catch{$p="$out\$name-error.txt";[string]$_.Exception.Message|Set-Content $p;Invoke-WebRequest -UseBasicParsing "$base/$name-error.txt" -Method Post -InFile $p|Out-Null;exit 1}
